import * as THREE from 'three';

const $ = id => document.getElementById(id);
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x9a8065);
scene.fog = new THREE.FogExp2(0x9a8065, 0.012);
const camera = new THREE.PerspectiveCamera(73, innerWidth / innerHeight, 0.08, 450);
camera.position.set(0, 1.72, 8);
const renderer = new THREE.WebGLRenderer({antialias:true, powerPreference:'high-performance'});
renderer.setSize(innerWidth, innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace; renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.25;
$('game').appendChild(renderer.domElement);

const mats = {
 sand: new THREE.MeshStandardMaterial({color:0x9a7954, roughness:1}), darkSand:new THREE.MeshStandardMaterial({color:0x786146,roughness:1}),
 concrete:new THREE.MeshStandardMaterial({color:0x77766b,roughness:.92}), darkConcrete:new THREE.MeshStandardMaterial({color:0x343a35,roughness:.85}),
 metal:new THREE.MeshStandardMaterial({color:0x303b37,metalness:.72,roughness:.4}), olive:new THREE.MeshStandardMaterial({color:0x4c5541,roughness:.83}),
 crate:new THREE.MeshStandardMaterial({color:0x62563f,roughness:.9}), warm:new THREE.MeshStandardMaterial({color:0xd9a25c,emissive:0x8c4b14,emissiveIntensity:1.6}),
 enemy:new THREE.MeshStandardMaterial({color:0x383c32,roughness:.82}), enemyCloth:new THREE.MeshStandardMaterial({color:0x72654a,roughness:1}),
};
scene.add(new THREE.HemisphereLight(0xc9d2cf,0x443323,1.45));
const moonLight = new THREE.DirectionalLight(0xffdfb1, 2.45); moonLight.position.set(-35,55,28); moonLight.castShadow=true; moonLight.shadow.mapSize.set(2048,2048); moonLight.shadow.camera.left=-55; moonLight.shadow.camera.right=55; moonLight.shadow.camera.top=55; moonLight.shadow.camera.bottom=-55; moonLight.shadow.bias=-.0002; scene.add(moonLight);
const fill = new THREE.DirectionalLight(0x9cb6c5,.48); fill.position.set(30,18,-32); scene.add(fill);
const hemiPoint = new THREE.PointLight(0xffb86a,1.3,25); hemiPoint.position.set(1,4,-18); scene.add(hemiPoint);

function box(parent, size, pos, mat, cast=true) { const m=new THREE.Mesh(new THREE.BoxGeometry(...size),mat); m.position.set(...pos); m.castShadow=cast; m.receiveShadow=true; parent.add(m); return m; }
function cylinder(parent, rt, rb, h, pos, mat, seg=8) { const m=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,seg),mat);m.position.set(...pos);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m; }
function seeded(seed){let s=seed>>>0;return()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296}}
const rand=seeded(9017);
function terrainHeight(x,z){return Math.sin(x*.13+z*.035)*1.5+Math.cos(z*.17-x*.03)*1.3+Math.sin((x+z)*.34)*.32;}
const terrainGeo=new THREE.PlaneGeometry(240,260,110,110); terrainGeo.rotateX(-Math.PI/2);
const p=terrainGeo.attributes.position; const colors=[];
for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i),h=terrainHeight(x,z);p.setY(i,h);const c=new THREE.Color().setHSL(.095+rand()*.015,.24,.31+rand()*.06);colors.push(c.r,c.g,c.b)}
terrainGeo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));terrainGeo.computeVertexNormals();
const ground=new THREE.Mesh(terrainGeo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));ground.receiveShadow=true;scene.add(ground);
// Far ridgelines: layered silhouettes make the valley feel enormous.
for(let layer=0;layer<3;layer++){
 const points=[];for(let i=0;i<=36;i++){const x=-130+i*7.3;const y=15+rand()*12+Math.sin(i*.62+layer)*7;points.push(new THREE.Vector2(x,y))}
 const shape=new THREE.Shape();shape.moveTo(-140,-14);shape.lineTo(points[0].x,points[0].y);for(const q of points)shape.lineTo(q.x,q.y);shape.lineTo(140,-14);shape.closePath();
 const mesh=new THREE.Mesh(new THREE.ShapeGeometry(shape),new THREE.MeshStandardMaterial({color:[0x685c4d,0x554f46,0x444943][layer],roughness:1}));mesh.position.set(0,layer*1.1,-110-layer*18);scene.add(mesh);
}
// Moon and a restrained scatter of stars.
const moon=new THREE.Mesh(new THREE.SphereGeometry(3.1,24,16),new THREE.MeshBasicMaterial({color:0xf4ddae}));moon.position.set(-31,34,-91);scene.add(moon);
const starGeo=new THREE.BufferGeometry(), starPoints=[];for(let i=0;i<260;i++)starPoints.push((rand()-.5)*190,17+rand()*80,-85-rand()*95);
starGeo.setAttribute('position',new THREE.Float32BufferAttribute(starPoints,3));scene.add(new THREE.Points(starGeo,new THREE.PointsMaterial({color:0xe9e1c9,size:.16,transparent:true,opacity:.7})));

// A narrow abandoned border outpost, lit by one failing sodium lamp.
function makeBuilding(x,z,w,h,d,mat=mats.concrete){const g=new THREE.Group();g.position.set(x,terrainHeight(x,z),z);scene.add(g);box(g,[w,h,d],[0,h/2,0],mat);box(g,[w+.5,.25,d+.5],[0,h+.12,0],mats.darkConcrete);return g;}
makeBuilding(-9,-27,13,5,8);makeBuilding(10,-36,9,4.2,7);makeBuilding(-21,-47,8,3.8,7);
// doorway / dark windows
box(scene,[2.1,2.8,.12],[-4.8,terrainHeight(-4.8,-22)+1.4,-22],mats.darkConcrete);
for(const x of [-12,-7,8,13,-24]){box(scene,[1.1,1.5,.12],[x,terrainHeight(x,-31)+2,-31],mats.darkConcrete);}
// perimeter barriers and sandbags
for(let i=0;i<12;i++){const z=-10-i*2.15;box(scene,[4.7,1.05,.75],[-13,terrainHeight(-13,z)+.48,z],i%3?mats.concrete:mats.darkConcrete);}
for(let i=0;i<9;i++){const x=-4+i*1.35;const b=cylinder(scene,.38,.42,.52,[x,terrainHeight(x,-14)+.3,-14],mats.crate,10);b.rotation.z=Math.PI/2;}
// scattered rocks, wreckage, scrub with crisp silhouettes
for(let i=0;i<110;i++){let x=(rand()-.5)*90,z=(rand()-.5)*110-12;if(Math.abs(x)<4&&z<4&&z>-40)continue;const s=.35+rand()*1.5;const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(s,0),i%4?mats.darkSand:mats.concrete);rock.position.set(x,terrainHeight(x,z)+s*.38,z);rock.scale.set(1,.48+rand()*.55,.9);rock.rotation.set(rand(),rand()*3,rand());rock.castShadow=true;rock.receiveShadow=true;scene.add(rock)}
for(let i=0;i<23;i++){const x=(rand()-.5)*62,z=-12-rand()*78;if(Math.abs(x)<5)continue;const g=new THREE.Group();g.position.set(x,terrainHeight(x,z),z);scene.add(g);cylinder(g,.04,.12,.8,[0,.4,0],mats.olive,5);for(let n=0;n<3;n++){const leaf=box(g,[.1,.65,.1],[(rand()-.5)*.24,.65,(rand()-.5)*.24],mats.olive,false);leaf.rotation.z=(rand()-.5)*.65;}}
// Ground-level utility props, cable spool and scattered containers.
function crateAt(x,z,s=1){const y=terrainHeight(x,z);const g=new THREE.Group();g.position.set(x,y,z);scene.add(g);box(g,[s,s*.75,s],[0,s*.38,0],mats.crate);for(let j=-1;j<=1;j++){box(g,[s*.94,.07,.07],[0,s*.38+j*s*.24,s*.51],mats.darkConcrete,false);box(g,[.07,s*.69,.07],[j*s*.38,s*.38,s*.51],mats.darkConcrete,false);}return g}
crateAt(-3,-8,1.2);crateAt(5,-23,1.5);crateAt(-17,-34,1.25);crateAt(16,-45,1.6);crateAt(3,-53,1.1);

// Objective markers are intentionally legible at a distance, but grounded in the scene.
const markerGroup=new THREE.Group();scene.add(markerGroup);
const markerRing=new THREE.Mesh(new THREE.TorusGeometry(1.05,.045,8,36),new THREE.MeshBasicMaterial({color:0xd8ff75}));markerRing.rotation.x=Math.PI/2;markerGroup.add(markerRing);
const markerBeam=new THREE.Mesh(new THREE.CylinderGeometry(.13,.75,5,20,1,true),new THREE.MeshBasicMaterial({color:0xd8ff75,transparent:true,opacity:.12,side:THREE.DoubleSide}));markerBeam.position.y=2.5;markerGroup.add(markerBeam);
const markerSprite=new THREE.Sprite(new THREE.SpriteMaterial({color:0xd8ff75,transparent:true,opacity:.88}));markerSprite.scale.set(1.5,.24,1);markerSprite.position.y=5.3;markerGroup.add(markerSprite);

// First-person rifle model, built from shaded geometry and attached to the camera.
const gun=new THREE.Group();camera.add(gun);scene.add(camera);gun.position.set(.32,-.31,-.62);gun.rotation.set(-.04,-.04,0);
const gunMetal=new THREE.MeshStandardMaterial({color:0x202723,metalness:.78,roughness:.3}), gunPoly=new THREE.MeshStandardMaterial({color:0x41493e,metalness:.16,roughness:.72}), rubber=new THREE.MeshStandardMaterial({color:0x171b18,roughness:.95});
box(gun,[.16,.19,.68],[0,0,-.25],gunMetal);box(gun,[.21,.2,.26],[0,-.015,.1],gunPoly);box(gun,[.135,.23,.17],[0,-.16,.28],rubber);box(gun,[.12,.34,.12],[0,-.12,-.14],gunPoly);
const barrel=cylinder(gun,.032,.035,.68,[0,.015,-.83],gunMetal,12);barrel.rotation.x=Math.PI/2;
box(gun,[.22,.1,.28],[0,.105,-.43],gunMetal);box(gun,[.06,.12,.26],[0,.18,-.43],rubber);
box(gun,[.09,.12,.08],[0,-.21,-.26],gunPoly);box(gun,[.08,.04,.11],[0,.06,-1.12],gunMetal);
// magazine
const mag=box(gun,[.105,.34,.16],[0,-.28,-.38],gunPoly);mag.rotation.x=-.14;
// iron sights
box(gun,[.055,.1,.065],[0,.16,-.95],gunMetal);box(gun,[.09,.065,.09],[0,.15,-.25],gunMetal);
const flash=new THREE.PointLight(0xffa65e,0,7);flash.position.set(0,0,-1.15);gun.add(flash);
const flashMesh=new THREE.Mesh(new THREE.ConeGeometry(.15,.55,8),new THREE.MeshBasicMaterial({color:0xffc36c,transparent:true,opacity:.9}));flashMesh.rotation.x=-Math.PI/2;flashMesh.position.set(0,.01,-1.4);gun.add(flashMesh);flashMesh.visible=false;

// State and mission flow.
let active=false,paused=false,health=100,ammo=30,reserve=120,reloading=false,ads=false, recoil=0, shotCooldown=0, fireHeld=false;
let yaw=0,pitch=0, walkTime=0, hitFlash=0, kills=0, elapsed=0, currentObjective=0, enemies=[];
const enemyGroup=new THREE.Group();scene.add(enemyGroup);
const objectives=[
 {title:'Reach the relay',desc:'Close in on the listening post.',pos:new THREE.Vector3(-8,0,-31),radius:3.3,idx:'OBJECTIVE 01 / 03'},
 {title:'Secure the site',desc:'Clear hostiles around the outpost.',pos:new THREE.Vector3(-8,0,-31),radius:4,idx:'OBJECTIVE 02 / 03'},
 {title:'Move to extraction',desc:'Reach the ridge marker. Keep moving.',pos:new THREE.Vector3(19,0,-57),radius:4,idx:'OBJECTIVE 03 / 03'}
];
function spawnEnemy(x,z){const g=new THREE.Group();g.position.set(x,terrainHeight(x,z),z);enemyGroup.add(g);
 const torso=box(g,[.53,.73,.32],[0,1.24,0],mats.enemy);torso.rotation.x=-.05;
 const vest=box(g,[.56,.42,.35],[0,1.31,-.015],mats.enemyCloth);vest.rotation.x=-.05;
 const head=new THREE.Mesh(new THREE.SphereGeometry(.19,10,8),mats.enemy);head.position.set(0,1.77,0);head.castShadow=true;g.add(head);
 const helmet=new THREE.Mesh(new THREE.SphereGeometry(.22,10,7,0,Math.PI*2,0,Math.PI*.53),mats.darkConcrete);helmet.position.set(0,1.84,0);helmet.castShadow=true;g.add(helmet);
 for(const side of [-1,1]){const limb=box(g,[.17,.65,.18],[side*.39,1.23,0],mats.enemy);limb.rotation.z=side*-.15;box(g,[.2,.72,.23],[side*.16,.47,0],mats.enemy);}
 const rifle=box(g,[.08,.09,.75],[.08,1.18,-.37],gunMetal);rifle.rotation.x=.1;
 g.userData={hp:100,attack:rand()*1.5,stagger:0,walk:rand()*4,alive:true};enemies.push(g);return g;}
spawnEnemy(-1,-26);spawnEnemy(-13,-39);spawnEnemy(5,-40);spawnEnemy(13,-52);spawnEnemy(-20,-57);
function updateObjective(){const o=objectives[currentObjective];$('objectiveIndex').textContent=o.idx;$('objectiveTitle').textContent=o.title;$('objectiveDesc').textContent=o.desc;markerGroup.position.set(o.pos.x,terrainHeight(o.pos.x,o.pos.z)+.1,o.pos.z);}
updateObjective();
function notify(text){const t=$('toast');t.textContent=text;t.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove('show'),1900)}
function startMission(){ $('intro').style.display='none';$('hud').style.display='block'; active=true; if(innerWidth>750)renderer.domElement.requestPointerLock?.(); }
$('startBtn').addEventListener('click',startMission);
document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&active&&innerWidth>750){paused=true;$('pauseTag').style.display='block';}else if(document.pointerLockElement){paused=false;$('pauseTag').style.display='none';}});
document.addEventListener('keydown',e=>{if(e.code==='Escape'&&active){if(document.pointerLockElement)document.exitPointerLock();else{renderer.domElement.requestPointerLock?.();paused=false;$('pauseTag').style.display='none';}}if(e.code==='KeyR')reload();if(e.code==='KeyF')shoot();if(e.code==='Space')e.preventDefault();});
document.addEventListener('mousemove',e=>{if(active&&!paused&&(document.pointerLockElement||innerWidth<=750)){yaw-=e.movementX*.0022;pitch-=e.movementY*.0019;pitch=THREE.MathUtils.clamp(pitch,-1.25,1.25);}});
renderer.domElement.addEventListener('click',()=>{if(active&&!paused&&innerWidth>750&&!document.pointerLockElement)renderer.domElement.requestPointerLock?.();});
renderer.domElement.addEventListener('mousedown',e=>{if(e.button===0&&active&&!paused){fireHeld=true;shoot();}if(e.button===2){ads=true;}});
window.addEventListener('mouseup',e=>{if(e.button===0)fireHeld=false;if(e.button===2)ads=false;});window.addEventListener('contextmenu',e=>e.preventDefault());

function reload(){if(!active||reloading||ammo===30||reserve<=0)return;reloading=true;notify('RELOADING');setTimeout(()=>{const n=Math.min(30-ammo,reserve);ammo+=n;reserve-=n;reloading=false;$('ammoNum').textContent=ammo;},1450)}
function shoot(){if(!active||paused||reloading||shotCooldown>0)return;if(ammo<=0){reload();return}ammo--;shotCooldown=.16;recoil=Math.min(recoil+.065,.18);flash.intensity=4;flashMesh.visible=true;setTimeout(()=>{flash.intensity=0;flashMesh.visible=false},55);$('ammoNum').textContent=ammo;
 const ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(0,0),camera);const hit=ray.intersectObjects(enemyGroup.children,true).find(h=>h.object.parent?.userData?.alive||h.object.parent?.parent?.userData?.alive);
 if(hit&&hit.distance<72){let target=hit.object;while(target.parent&&!target.userData.alive)target=target.parent;if(target.userData.alive){target.userData.hp-=hit.object.geometry?.type==='SphereGeometry'?72:38;target.userData.stagger=.25;const hm=$('hitmarker');hm.classList.add('show');setTimeout(()=>hm.classList.remove('show'),100);if(target.userData.hp<=0){target.userData.alive=false;kills++;target.userData.fall=0;notify('HOSTILE DOWN');}else notify('TARGET HIT');}}
}
function setFire(v){fireHeld=v;if(v)shoot()}
$('fireBtn').addEventListener('pointerdown',e=>{e.preventDefault();setFire(true)});window.addEventListener('pointerup',()=>setFire(false));
$('reloadBtn').addEventListener('pointerdown',e=>{e.preventDefault();reload()});$('aimBtn').addEventListener('pointerdown',e=>{e.preventDefault();ads=!ads;$('aimBtn').classList.toggle('active',ads)});
// Mobile look drag and virtual move stick.
let lastTouch=null;renderer.domElement.addEventListener('touchstart',e=>{if(e.target.closest('.touch-actions,.stick'))return;if(active&&e.touches.length){lastTouch={x:e.touches[0].clientX,y:e.touches[0].clientY};}},{passive:true});renderer.domElement.addEventListener('touchmove',e=>{if(!active||!lastTouch||e.target.closest('.touch-actions,.stick'))return;const t=e.touches[0];yaw-=(t.clientX-lastTouch.x)*.004;pitch=THREE.MathUtils.clamp(pitch-(t.clientY-lastTouch.y)*.003,-1.25,1.25);lastTouch={x:t.clientX,y:t.clientY};},{passive:true});renderer.domElement.addEventListener('touchend',()=>lastTouch=null);
const stick=$('stick');let stickPointer=null,stickX=0,stickY=0;stick.addEventListener('pointerdown',e=>{e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)moveStick(e)});function moveStick(e){const r=stick.getBoundingClientRect();stickX=THREE.MathUtils.clamp((e.clientX-(r.left+r.width/2))/(r.width*.37),-1,1);stickY=THREE.MathUtils.clamp((e.clientY-(r.top+r.height/2))/(r.height*.37),-1,1);stick.style.setProperty('--sx',`${stickX*25}px`);stick.style.setProperty('--sy',`${stickY*25}px`);stick.style.background=`radial-gradient(circle at calc(50% + ${stickX*25}px) calc(50% + ${stickY*25}px),#d8ff7555,#12181661 45%)`;}
for(const ev of ['pointerup','pointercancel'])stick.addEventListener(ev,()=>{stickPointer=null;stickX=stickY=0;stick.style.background=''});

// Dust motes and thin drifting smoke catch the moonlight without obscuring the view.
const dustGeo=new THREE.BufferGeometry(), dustPos=new Float32Array(180*3);for(let i=0;i<180;i++){dustPos[i*3]=(rand()-.5)*48;dustPos[i*3+1]=1+rand()*12;dustPos[i*3+2]=-rand()*85+5;}dustGeo.setAttribute('position',new THREE.BufferAttribute(dustPos,3));const dust=new THREE.Points(dustGeo,new THREE.PointsMaterial({color:0xe4c89c,size:.085,transparent:true,opacity:.27,depthWrite:false}));scene.add(dust);
// Radio mast at the listening post, with a red aviation lamp and a small relay beacon.
const mast=new THREE.Group();mast.position.set(-8,terrainHeight(-8,-31),-31);scene.add(mast);
for(let i=0;i<4;i++){const y=i*1.35;cylinder(mast,.035,.045,1.4,[0,y+.7,0],mats.metal,6);const brace=box(mast,[.1,.1,1.7],[0,y+.7,0],mats.metal,false);brace.rotation.y=Math.PI/4;const brace2=brace.clone();brace2.rotation.y=-Math.PI/4;mast.add(brace2);}
cylinder(mast,.025,.025,2.4,[0,6.1,0],mats.metal,6);const antennaLamp=new THREE.PointLight(0xff5143,1.3,9);antennaLamp.position.set(0,6.4,0);mast.add(antennaLamp);
// A distant searchlight paints a slow arc through the haze.
const searchTarget=new THREE.Object3D();searchTarget.position.set(8,2,-42);scene.add(searchTarget);const search=new THREE.SpotLight(0xffd69a,18,85,Math.PI/10,.6,1.5);search.position.set(10,8,-35);search.target=searchTarget;scene.add(search);scene.add(search.target);search.castShadow=false;

function finishMission(){active=false;document.exitPointerLock?.();$('hud').style.display='none';$('mobileControls').style.display='none';const intro=$('intro');intro.style.display='grid';intro.innerHTML=`<section class="card"><div class="kicker">MISSION COMPLETE • 04:32 LOCAL</div><h1>EXFIL<span>SECURED</span></h1><div class="subline">OPERATION DUST SIGNAL &nbsp; / &nbsp; DEBRIEF</div><div class="rule"></div><p class="brief">The relay drive is safe. Intelligence confirms the listening post was compromised—but the team made it out before dawn.</p><div class="mission-meta"><div><label>HOSTILES NEUTRALIZED</label><strong>${kills} / 5</strong></div><div><label>VITALS</label><strong>${health}%</strong></div><div><label>RATING</label><strong>${health>60?'SILENT PROFESSIONAL':'MISSION READY'}</strong></div></div><button class="button" id="againBtn">PLAY AGAIN &nbsp; ↻</button><div class="hint">BLACKTIDE CAMPAIGN • CHAPTER 01 COMPLETE</div></section>`;$('againBtn').addEventListener('click',()=>location.reload());}
function advanceObjective(){currentObjective++;if(currentObjective>=objectives.length){notify('EXTRACTION REACHED');setTimeout(finishMission,1800);return}updateObjective();notify(currentObjective===1?'SITE REACHED • CLEAR THE AREA':'AREA SECURE • MOVE TO EXTRACTION');}
function damagePlayer(amount){health=Math.max(0,health-amount);$('healthNum').textContent=health;$('healthBar').style.width=health+'%';hitFlash=.2;document.body.style.boxShadow='inset 0 0 90px #9d2929aa';setTimeout(()=>document.body.style.boxShadow='',190);if(health<=0){active=false;document.exitPointerLock?.();$('hud').style.display='none';$('mobileControls').style.display='none';const intro=$('intro');intro.style.display='grid';intro.innerHTML=`<section class="card"><div class="kicker">SIGNAL LOST</div><h1>MISSION<span>FAILED</span></h1><div class="rule"></div><p class="brief">The operation is over. Reset, take a breath, and try another approach.</p><button class="button" id="againBtn">REDEPLOY &nbsp; ↻</button></section>`;$('againBtn').addEventListener('click',()=>location.reload());}}
function updateEnemies(dt){let living=0;for(const e of enemies){const u=e.userData;if(!u.alive){if(u.fall<1){u.fall=(u.fall||0)+dt*1.7;e.rotation.x=-Math.min(1.35,u.fall*1.35);e.position.y-=dt*.35;}else e.visible=false;continue}living++;
 const dx=camera.position.x-e.position.x,dz=camera.position.z-e.position.z,dist=Math.hypot(dx,dz);u.walk+=dt*5;u.attack-=dt;
 if(dist>13&&dist<58){const step=Math.min(dt*.72,dist-11);e.position.x+=dx/dist*step;e.position.z+=dz/dist*step;e.position.y=terrainHeight(e.position.x,e.position.z);e.rotation.y=Math.atan2(-dx,-dz);e.position.y+=Math.sin(u.walk)*.025;}
 if(dist<40&&u.attack<=0){u.attack=1.5+rand()*1.5;const aimError=.45+dist*.018;if(rand()>.26){const dmg=Math.max(3,Math.round((15-dist*.18)*(1+rand()*.45)));damagePlayer(dmg);const beamMat=new THREE.LineBasicMaterial({color:0xff9a59,transparent:true,opacity:.85});const pts=[new THREE.Vector3(e.position.x,1.45+e.position.y,e.position.z),new THREE.Vector3(camera.position.x+(rand()-.5)*aimError, camera.position.y+(rand()-.5)*aimError,camera.position.z)];const beam=new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),beamMat);scene.add(beam);setTimeout(()=>{scene.remove(beam);beam.geometry.dispose();beamMat.dispose()},80);}}
 }
 $('threat').textContent=living>3?'HIGH':living?'ACTIVE':'CLEAR';if(currentObjective===1&&living===0)advanceObjective();}
const keys=new Set();window.addEventListener('keydown',e=>{keys.add(e.code);if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{fireHeld=false;});
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04);elapsed+=dt;shotCooldown=Math.max(0,shotCooldown-dt);recoil=Math.max(0,recoil-dt*.42);if(fireHeld&&shotCooldown<=0)shoot();
 if(active&&!paused){let forward=0,side=0;if(keys.has('KeyW')||keys.has('ArrowUp'))forward+=1;if(keys.has('KeyS')||keys.has('ArrowDown'))forward-=1;if(keys.has('KeyD')||keys.has('ArrowRight'))side+=1;if(keys.has('KeyA')||keys.has('ArrowLeft'))side-=1;forward-=stickY;side+=stickX;
